const fs = require('fs');
const CACHE_PATH = 'C:\\Users\\sarab\\Documents\\EstiNova\\teachers_cache.json';

let rows = [];
try {
  rows = JSON.parse(fs.readFileSync(CACHE_PATH, 'utf-8'));
} catch(e) {
  rows = [];
}

const updated = {
  'First Name':    $input.first().json['First Name']    || '',
  'Last Name':     $input.first().json['Last Name']     || '',
  'Email Address': $input.first().json['Email Address'] || '',
  'Promo / Section':         $input.first().json['Promo / Section']         || '',
  'Module(s)':         $input.first().json['Module(s)']         || ''
};


if (!updated['Email Address'].trim()) {
  return [{ json: { status: '⚠️ Ignoré - email vide' } }];
}

const idx = rows.findIndex(r =>
  (r['Email Address'] || '').toLowerCase().trim() ===
  updated['Email Address'].toLowerCase().trim()
);

if (idx >= 0) {
  rows[idx] = updated;
} else {
  rows.push(updated);
}

fs.writeFileSync(CACHE_PATH, JSON.stringify(rows, null, 2), 'utf-8');

return [{
  json: {
    status: '✅ Upsert OK',
    action: idx >= 0 ? 'mise à jour' : 'ajout',
    email: updated['Email Address'],
    totalRows: rows.length,
    updatedAt: new Date().toISOString()
  }
}];

const fs = require('fs');
const CACHE_PATH = 'C:\\Users\\sarab\\Documents\\EstiNova\\teachers_cache.json';

const email = ($input.first().json.body?.email || '').toLowerCase().trim();

let rows = [];
try {
  const raw = fs.readFileSync(CACHE_PATH, 'utf-8');
  rows = JSON.parse(raw);
} catch (e) {
  // Cache absent
}

const student = rows.find(r =>
  (r['Email Address'] || '').toLowerCase().trim() === email
) || {
  'First Name': '',
  'Last Name': '',
  'Email Address': email,
  'Promo / Section': '',
  'Module(s)': ''
};

return [{ json: student }];

