  admin = $('Get Admin From Sheet').first().json || {};
} catch (e) {
  admin = { Role: 'NOT_FOUND' };
}

const auditEntry = {
  timestamp: new Date().toISOString(),
  event: 'UNAUTHORIZED_ACCESS_ATTEMPT',
  email_attempted: body.email || 'UNKNOWN',
  role_found: admin.Role || 'NOT_FOUND',
  session_id: body.sessionId || 'NO_SESSION',
  ip: body.ip || 'UNKNOWN'
};

console.log('[SECURITY AUDIT]', JSON.stringify(auditEntry));
